#import "../SBCPUMemorySample.h"
#include <assert.h>
static int mode=0,pages=0,stats=0;
static uint64_t inactive=0; static vm_size_t pageSize=16384;
static kern_return_t page(host_t h,vm_size_t *p){(void)h;pages++;*p=mode==2?0:pageSize;return mode==1?KERN_FAILURE:KERN_SUCCESS;}
static kern_return_t query(host_t h,host_flavor_t f,host_info64_t out,mach_msg_type_number_t *n){(void)h;assert(f==HOST_VM_INFO64);stats++;if(mode==3)return KERN_FAILURE;if(mode==4)*n=HOST_VM_INFO64_COUNT-1;((vm_statistics64_t)out)->free_count=100;((vm_statistics64_t)out)->inactive_count=(natural_t)inactive;return KERN_SUCCESS;}
int main(void){@autoreleasepool{for(mode=0;mode<=4;mode++){SBCPUMemoryMetrics m=SBCPUMemoryReadWith(1,8ULL<<30,page,query);assert(m.valid==(mode==0));assert(m.used_bytes==(mode==0?(8ULL<<30)-100ULL*16384:0));}assert(pages==5&&stats==3);assert(!SBCPUMemoryReadWith(MACH_PORT_NULL,8ULL<<30,page,query).valid);mode=0;assert(!SBCPUMemoryReadWith(1,0,page,query).valid);SBCPUMemoryPageCounters overflow={UINT64_MAX};SBCPUMemoryMetrics m;assert(SBCPUMemoryMetricsCompute(&overflow,UINT64_MAX,8ULL<<30,&m)&&m.used_bytes==0);for(int size=0;size<2;size++){pageSize=size?4096:16384;inactive=0;SBCPUMemoryMetrics x=SBCPUMemoryReadWith(1,8ULL<<30,page,query);inactive=1000000;SBCPUMemoryMetrics y=SBCPUMemoryReadWith(1,8ULL<<30,page,query);assert(x.valid&&y.valid&&x.used_bytes==y.used_bytes);assert(x.total_bytes-x.used_bytes==100ULL*pageSize);assert(x.page_size==pageSize);}SBCPUMemoryMetrics a=SBCPUMemoryCachedSample(),b=SBCPUMemoryCachedSample();assert(a.valid==b.valid&&a.used_bytes==b.used_bytes);puts("PASS production free-only vs inactive, 4K/16K pages, Mach errors/overflow/clamp/cache");}return 0;}
